// =============================================================================
// Code Pro — Fetch Sitemap XML (discover + fetch raw body)
// =============================================================================
// MODE: Run Once for All Items (required for multi-site batches)
//
// NODE OPTIONS: Max Output Items = 10000 (Timeout left unset → node default).
// timeoutMs BELOW is ONLY per HTTP request (axios), NOT the node soft timeout.
//
// Why utils.sitemap beats hand-rolled axios + COMMON_SITEMAP_PATHS loops:
//   1) Parallel candidate probes (concurrency) instead of sequential for-loops
//   2) All robots.txt Sitemap: lines (not only the first)
//   3) gzip .xml.gz support
//   4) attempts[] diagnostics when found:false (no silent catch → null)
//   5) Shared AbortSignal with node Timeout when Timeout > 0
//   6) Same output contract for rankers: website, sourceUrl, rawXml, found
//
// Full guide: docs/SITEMAP.md
// =============================================================================

const sites = $input.all().map((i) => {
  const j = i.json || i;
  return j.Website || j.website || null;
});

const results = await utils.sitemap.fromWebsites(sites, {
  expand: false,           // fetch only — do not walk indexes to page URLs yet
  includeRawXml: true,     // return the raw sitemap body for downstream nodes
  websiteConcurrency: 3,   // how many websites in parallel
  concurrency: 4,          // candidate URL probes per website
  timeoutMs: 8000,         // per-request HTTP timeout (ms), not node Options → Timeout
});

return results.map((r, index) => ({
  json: {
    // Core contract (drop-in for SuperCode "Fetch Sitemap XML" consumers)
    website: r.website || null,
    sourceUrl: r.sourceUrl,
    rawXml: r.rawXml,
    found: r.found,
    // Extras (safe to ignore downstream)
    kind: r.kind,
    base: r.base,
    robotsSitemaps: r.robotsSitemaps,
    attempts: r.found ? undefined : r.attempts,
    error: r.website
      ? r.found
        ? undefined
        : 'No sitemap XML found (see attempts)'
      : 'No website field on input item',
  },
  pairedItem: { item: index },
}));
